// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.context/** * NOUS — Device context. * * Snapshot of device state at the moment a request is processed. Used by * guardrails (Layer 3 thermal/RAM check, battery-aware routing) and by * skill selection (some skills need GPU, some need network). * * Built by [com.roshan.persona.brain.orchestrator.BrainPreProcessor] from * Android system services (PowerManager, ActivityManager, ConnectivityManager). * * @see <a href="docs/spec/module2-spec-review.pdf">§7.3 Thermal + RAM Guardrails</a> */data class DeviceContext(    /** Thermal throttling status (0-6, see POWER_* constants). */    val thermalStatus: ThermalStatus,    /** Available RAM in MB (for LLM model selection). */    val availableRamMb: Int,    /** Battery level 0-100. */    val batteryLevel: Int,    /** Whether device is currently charging. */    val isCharging: Boolean,    /** Whether device has network connectivity. */    val isOnline: Boolean,    /** Network type (affects cloud LLM decisions). */    val networkType: NetworkType,    /** Whether Vulkan GPU is available (for llama.cpp GPU acceleration). */    val gpuAvailable: Boolean,    /** GPU VRAM in MB (for LLM model selection — models must fit in VRAM). */    val gpuVramMb: Int,)/** * Thermal status — maps to Android's PowerManager.THERMAL_STATUS_* constants. * * NONE: device not throttling * LIGHT: minor throttling, can still run LLM * MODERATE: noticeable throttling, defer heavy LLM if battery low * SEVERE: heavy throttling, defer all LLM to cloud * CRITICAL: emergency throttling, defer everything */enum class ThermalStatus {    NONE,    LIGHT,    MODERATE,    SEVERE,    CRITICAL,    EMERGENCY,    ;    /** Whether this status is at or above [other] severity. */    fun isAtLeast(other: ThermalStatus): Boolean = ordinal >= other.ordinal}enum class NetworkType {    WIFI,    CELLULAR_4G,    CELLULAR_5G,    CELLULAR_3G,    CELLULAR_2G,    NONE,    ;    /** Whether this network is suitable for cloud LLM streaming. */    val isSuitableForCloudLlm: Boolean        get() = this == WIFI || this == CELLULAR_5G || this == CELLULAR_4G}